// @ts-ignore generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  scheduled(_event: unknown, env: { CRON_SECRET?: string }, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const request = new Request("https://yvusd-api.yearn.fi/api/sync", {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then((res: Response) => {
        if (!res.ok) console.error(`scheduled /api/sync failed: ${res.status}`);
      }),
    );
  },
};
